<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Poczta SMTP'; ?>
<div class="page-head"><div><p class="eyebrow">Administracja</p><h1>Poczta SMTP</h1></div></div><?php if($notice):?><div class="alert success"><?=Html::e($notice)?></div><?php endif;?><?php if($error):?><div class="alert danger"><?=Html::e($error)?></div><?php endif;?>
<div class="split"><section class="card"><h2>Konfiguracja</h2><form method="post" action="<?=Html::e(Url::to('/admin/mail'))?>" class="stack-form"><?=Csrf::field()?><label>SMTP host<input name="host" value="<?=Html::e($settings['host'])?>" required></label><label>Port<input type="number" name="port" min="1" max="65535" value="<?=Html::e($settings['port'])?>" required></label><label>Szyfrowanie<select name="encryption"><option value="tls" <?=$settings['encryption']==='tls'?'selected':''?>>STARTTLS</option><option value="ssl" <?=$settings['encryption']==='ssl'?'selected':''?>>TLS od połączenia</option><option value="none" <?=$settings['encryption']==='none'?'selected':''?>>Brak</option></select></label><label>Użytkownik<input name="username" value="<?=Html::e($settings['username'])?>"></label><label>Hasło<input type="password" name="password" autocomplete="new-password" placeholder="Pozostaw puste, aby zachować obecne"></label><label>From address<input type="email" name="from_address" value="<?=Html::e($settings['from_address'])?>" required></label><label>From name<input name="from_name" value="<?=Html::e($settings['from_name'])?>" required></label><button class="button">Zapisz</button></form></section><section class="card"><h2>Test</h2><p class="muted">Wiadomość jest dodawana do kolejki i wysyłana przez mechanizm jobs.</p><form method="post" action="<?=Html::e(Url::to('/admin/mail/test'))?>" class="stack-form"><?=Csrf::field()?><label>Adres odbiorcy<input type="email" name="to" required></label><button class="button secondary">Wyślij wiadomość testową</button></form></section></div>
